import json

def find_most_active_user(channels):
    user_message_count = {}
    for channel in channels:
        messages = read_channel_messages(channel)
        for message in messages:
            user = message['user']
            if user not in user_message_count:
                user_message_count[user] = 0
            user_message_count[user] += 1
    most_active_user = max(user_message_count, key=user_message_count.get)
    return most_active_user

def read_channel_messages(channel):
    # This function should read the messages from the given channel
    # For simplicity, let's assume it returns a list of messages
    # where each message is a dictionary with 'user' and 'text' keys
    return [{'user': 'user1', 'text': 'message1'}, {'user': 'user2', 'text': 'message2'}]

def send_direct_message(recipient, body):
    # This function should send a direct message to the recipient
    print(f"Sending message to {recipient}: {body}")

def main():
    channels = []  # Get the list of channels
    most_active_user = find_most_active_user(channels)
    send_direct_message(most_active_user, "Congrats on being the most active user!")

if __name__ == "__main__":
    main()
